package httpapi

const docsHTML = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>BaiduPCS-Go API</title><style>body{font:16px system-ui;max-width:960px;margin:40px auto;padding:0 24px;color:#243044}input,textarea,select,button{font:inherit;margin:6px 0;padding:8px;box-sizing:border-box}input,textarea,pre{width:100%}textarea{height:140px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f6f9;padding:16px;box-sizing:border-box}button{cursor:pointer}label{display:block}</style><h1>BaiduPCS-Go HTTP API</h1><p>API v1 · P1 运行基础。账号和文件业务仍按 capabilities 声明阶段开放。</p><p>完整契约：<code>GET /api/v1/openapi.json</code>。所有请求使用服务 Bearer token；百度凭据不作为服务身份。</p><label>服务 token<input id="token" type="password" autocomplete="off"></label><label>方法<select id="method"><option>GET</option><option>PATCH</option><option>POST</option></select></label><label>路径<input id="path" value="/api/v1/system"></label><label>If-Match（配置更新需要强 ETag）<input id="etag" placeholder='"1"'></label><label>JSON 请求体<textarea id="body">{}</textarea></label><button id="send">发送请求</button><pre id="result">尚未发送。token 仅保留在本页内存，不写入浏览器存储。</pre><script>document.getElementById('send').onclick=async()=>{const el=id=>document.getElementById(id),out=el('result');try{const u=new URL(el('path').value,location.origin);if(u.origin!==location.origin||!u.pathname.startsWith('/api/v1/'))throw Error('仅允许访问本服务 /api/v1/');const method=el('method').value,headers={Authorization:'Bearer '+el('token').value};if(el('etag').value)headers['If-Match']=el('etag').value;let body;if(method!=='GET'){headers['Content-Type']='application/json';body=el('body').value}const r=await fetch(u,{method,headers,body,credentials:'omit',cache:'no-store',redirect:'error'});out.textContent=r.status+' '+r.statusText+'\nETag: '+(r.headers.get('ETag')||'')+'\n\n'+await r.text()}catch(e){out.textContent=e.message}};</script></html>`
